import sys

def read_input():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    current = [input[i] for i in range(2, 2 + n)]
    desired = [input[i] for i in range(2 + n, 2 + 2 * n)]
    return n, m, current, desired

def solve(n, m, current, desired):
    operations = []
    for i in range(n - 1):
        for j in range(m - 1):
            if current[i][j] + current[i][j+1] + current[i+1][j] + current[i+1][j+1] != desired[i][j] + desired[i][j+1] + desired[i+1][j] + desired[i+1][j+1]:
                operations.append((i + 1, j + 1))
                current[i] = current[i][:j] + ('R' if current[i][j] == 'L' else 'L') + current[i][j+1:]
                current[i+1] = current[i+1][:j] + ('D' if current[i+1][j] == 'U' else 'U') + current[i+1][j+1:]
                current[i] = current[i][:j+1] + ('L' if current[i][j+1] == 'R' else 'R') + current[i][j+2:]
                current[i+1] = current[i+1][:j+1] + ('U' if current[i+1][j+1] == 'D' else 'D') + current[i+1][j+2:]
    if current == desired:
        return len(operations), operations
    else:
        return -1, []

def main():
    n, m, current, desired = read_input()
    k, operations = solve(n, m, current, desired)
    if k == -1:
        print(-1)
    else:
        print(k)
        for op in operations:
            print(op[0], op[1])

main()
